/**
 * 3D Garba Jukebox Application Orchestrator
 */

import '../styles.css';

import { SONGS } from './data/songs.js';
import { THEMES, themeById } from './data/themes.js';
import { audio } from './core/audio.js';
import { GarbaScene3D } from './scene/garba3d.js';
import { SongDrawer } from './components/drawer.js';
import { JoinModal } from './components/joinModal.js';
import { DandiyaClashGame } from './components/dandiyaGame.js';

class GarbaApp {
  constructor() {
    this.currentTheme = THEMES[0];
    this.currentTrackIndex = 0;
    this.currentTrack = SONGS[0];
    this.isShuffled = false;
    this.playOrder = SONGS.map((_, i) => i);

    // Instances
    this.scene3d = null;
    this.songDrawer = null;
    this.joinModal = null;
    this.dandiyaGame = null;

    // Toast Timer
    this.toastTimer = null;
  }

  init() {
    // 1. Initialize 3D Scene
    const sceneContainer = document.getElementById('scene-container');
    this.scene3d = new GarbaScene3D({
      container: sceneContainer,
      onDancerClick: (dancerData) => this.showDancerCard(dancerData),
      onFloorSeek: (fraction) => audio.seekFraction(fraction)
    });

    // 2. Initialize Components
    this.songDrawer = new SongDrawer({
      songs: SONGS,
      onPlayTrack: (track) => this.playSong(track),
      getCurrentTrack: () => this.currentTrack
    });

    this.joinModal = new JoinModal({
      onJoinSuccess: (userData) => {
        this.scene3d.addCustomUserAvatar(userData);
        this.toast(`🎉 Welcome <strong>${userData.name}</strong> to the Garba Circle!`);
      }
    });

    this.dandiyaGame = new DandiyaClashGame();

    // 3. Audio Engine & YouTube Setup
    audio.mountYouTubePlayer('yt-player', () => {
      // Audio engine ready
    });

    audio.onPlayStateChange = (isPlaying) => {
      this.scene3d.setPlaying(isPlaying);
      this.updatePlayPauseUI(isPlaying);
      document.body.classList.toggle('is-playing', isPlaying);
    };

    audio.onTimeUpdate = ({ current, duration, fraction }) => {
      this.scene3d.setProgress(fraction);
      this.updateProgressUI(current, duration, fraction);
    };

    audio.onBeat = ({ index }) => {
      this.pulseBeatIndicator(index);
    };

    audio.onTrackEnded = () => {
      this.nextTrack();
    };

    // 4. Build Theme Buttons & UI
    this.buildThemeSelector();
    this.buildClock();
    this.buildPresence();
    this.setupDockControls();
    this.setupKeybindings();

    // 5. Set Initial Theme & Cue Song
    this.applyTheme(this.currentTheme, false);
    this.loadTrackUI(this.currentTrack);
    audio.loadTrack(this.currentTrack, false); // Cue ready
  }

  /* ─────────────────────────────────────────────────────────────
     Theme Management
     ───────────────────────────────────────────────────────────── */

  buildThemeSelector() {
    const container = document.getElementById('theme-bar');
    container.innerHTML = '';

    THEMES.forEach((theme) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = `theme-chip ${theme.id === this.currentTheme.id ? 'active' : ''}`;
      btn.dataset.theme = theme.id;
      btn.style.setProperty('--chip-color', theme.palette.primary);
      btn.style.setProperty('--chip-bg', theme.palette.surface);

      btn.innerHTML = `
        <span class="chip-dot"></span>
        <span class="chip-guj" lang="gu">${theme.guj}</span>
        <span class="chip-name">${theme.name}</span>
      `;

      btn.addEventListener('click', () => {
        audio.playDhol(0.35);
        this.applyTheme(theme, true);
      });

      container.appendChild(btn);
    });
  }

  applyTheme(theme, announce = true) {
    this.currentTheme = theme;
    document.documentElement.dataset.theme = theme.id;
    document.documentElement.dataset.ground = theme.ground;

    // Update 3D Scene
    this.scene3d.setTheme(theme);
    this.scene3d.setBpm(this.currentTrack ? this.currentTrack.bpm : theme.bpm);

    // Update active chip
    document.querySelectorAll('.theme-chip').forEach((c) => {
      c.classList.toggle('active', c.dataset.theme === theme.id);
    });

    if (announce) {
      this.toast(`<strong>${theme.guj}</strong>: ${theme.tagline}`);
    }
  }

  /* ─────────────────────────────────────────────────────────────
     Track Controls
     ───────────────────────────────────────────────────────────── */

  playSong(track) {
    const idx = SONGS.findIndex((s) => s.id === track.id);
    if (idx > -1) {
      this.currentTrackIndex = idx;
    }
    this.currentTrack = track;
    this.loadTrackUI(track);
    this.scene3d.setBpm(track.bpm);

    // Auto-match theme if genre aligns
    const matchingTheme = THEMES.find((t) => t.id === track.genre);
    if (matchingTheme && matchingTheme.id !== this.currentTheme.id) {
      this.applyTheme(matchingTheme, false);
    }

    audio.loadTrack(track, true);
    this.toast(`🎶 Now Playing: <strong>${track.titleGuj || track.title}</strong> by ${track.artist}`);
  }

  nextTrack() {
    audio.playDhol(0.4);
    if (this.isShuffled) {
      this.currentTrackIndex = Math.floor(Math.random() * SONGS.length);
    } else {
      this.currentTrackIndex = (this.currentTrackIndex + 1) % SONGS.length;
    }
    this.playSong(SONGS[this.currentTrackIndex]);
  }

  prevTrack() {
    audio.playDhol(0.4);
    this.currentTrackIndex = (this.currentTrackIndex - 1 + SONGS.length) % SONGS.length;
    this.playSong(SONGS[this.currentTrackIndex]);
  }

  togglePlay() {
    audio.playDhol(0.45);
    const isPlaying = audio.togglePlay();
    this.updatePlayPauseUI(isPlaying);
  }

  toggleShuffle() {
    this.isShuffled = !this.isShuffled;
    const btn = document.getElementById('btn-shuffle');
    if (btn) btn.classList.toggle('active', this.isShuffled);
    this.toast(this.isShuffled ? '🔀 Shuffle On' : '➡️ Continuous Mode');
  }

  loadTrackUI(track) {
    document.getElementById('track-title').textContent = track.title;
    document.getElementById('track-title-guj').textContent = track.titleGuj || '';
    document.getElementById('track-artist').textContent = track.artist;
    document.getElementById('track-cover').src = track.cover;
    document.getElementById('track-cover').alt = track.title;
    document.getElementById('track-yt-link').href = `https://www.youtube.com/watch?v=${track.id}`;
    document.getElementById('track-step-badge').textContent = track.steps || 'Garba';

    const durM = Math.floor(track.duration / 60);
    const durS = track.duration % 60;
    document.getElementById('time-total').textContent = `${durM}:${durS < 10 ? '0' : ''}${durS}`;
    document.getElementById('time-elapsed').textContent = '0:00';
    document.getElementById('seek-progress-fill').style.width = '0%';
  }

  updatePlayPauseUI(isPlaying) {
    const playBtn = document.getElementById('btn-play');
    if (playBtn) {
      playBtn.classList.toggle('playing', isPlaying);
      playBtn.setAttribute('aria-label', isPlaying ? 'Pause Garba' : 'Play Garba');
    }
  }

  updateProgressUI(current, duration, fraction) {
    const curM = Math.floor(current / 60);
    const curS = Math.floor(current % 60);
    document.getElementById('time-elapsed').textContent = `${curM}:${curS < 10 ? '0' : ''}${curS}`;

    const durM = Math.floor(duration / 60);
    const durS = Math.floor(duration % 60);
    document.getElementById('time-total').textContent = `${durM}:${durS < 10 ? '0' : ''}${durS}`;

    document.getElementById('seek-progress-fill').style.width = `${fraction * 100}%`;
  }

  pulseBeatIndicator(index) {
    const dots = document.querySelectorAll('.beat-dot');
    dots.forEach((d, i) => {
      d.classList.toggle('hit', i === index);
    });
  }

  /* ─────────────────────────────────────────────────────────────
     Dock & HUD Controls
     ───────────────────────────────────────────────────────────── */

  setupDockControls() {
    // Play/Pause
    document.getElementById('btn-play').addEventListener('click', () => this.togglePlay());
    document.getElementById('btn-next').addEventListener('click', () => this.nextTrack());
    document.getElementById('btn-prev').addEventListener('click', () => this.prevTrack());
    document.getElementById('btn-shuffle').addEventListener('click', () => this.toggleShuffle());

    // Open Song Drawer
    document.getElementById('btn-vault').addEventListener('click', () => {
      audio.playManjira(0.5);
      this.songDrawer.open();
    });

    // Seek Bar Click
    const progressBar = document.getElementById('seek-bar-track');
    progressBar.addEventListener('click', (e) => {
      const rect = progressBar.getBoundingClientRect();
      const fraction = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      audio.seekFraction(fraction);
    });

    // Camera Angle Preset Buttons
    document.querySelectorAll('.cam-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        audio.playManjira(0.4);
        document.querySelectorAll('.cam-btn').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        this.scene3d.setCameraPreset(btn.dataset.cam);
      });
    });

    // Dandiya Clash Button
    document.getElementById('btn-dandiya-clash').addEventListener('click', () => {
      this.dandiyaGame.toggle();
    });

    // Join Circle Button
    document.getElementById('btn-join-circle').addEventListener('click', () => {
      this.joinModal.open();
    });

    // Dancer Card Dismiss
    document.getElementById('dancer-card-close').addEventListener('click', () => {
      document.getElementById('dancer-card').classList.remove('show');
    });

    // Fullscreen
    document.getElementById('btn-fullscreen').addEventListener('click', () => {
      if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch(() => {});
      } else {
        document.exitFullscreen().catch(() => {});
      }
    });
  }

  showDancerCard(dancerData) {
    audio.playDandiya(0.6);
    const card = document.getElementById('dancer-card');
    document.getElementById('card-name').textContent = dancerData.name;
    document.getElementById('card-city').textContent = dancerData.city;
    document.getElementById('card-step').textContent = dancerData.step;
    card.classList.add('show');
  }

  /* ─────────────────────────────────────────────────────────────
     Clock & Presence
     ───────────────────────────────────────────────────────────── */

  buildClock() {
    const clockEl = document.getElementById('hud-clock');
    const update = () => {
      const now = new Date();
      clockEl.textContent = now.toLocaleTimeString('en-IN', {
        timeZone: 'Asia/Kolkata',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: true
      }) + ' IST';
    };
    update();
    setInterval(update, 1000);
  }

  buildPresence() {
    const crowdEl = document.getElementById('hud-crowd');
    let crowd = 98420;
    setInterval(() => {
      crowd += Math.floor((Math.random() - 0.45) * 15);
      crowdEl.textContent = crowd.toLocaleString('en-IN');
      this.scene3d.setCrowd(crowd);
    }, 3500);
  }

  setupKeybindings() {
    window.addEventListener('keydown', (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

      if (e.code === 'Space' && !this.dandiyaGame.isActive) {
        e.preventDefault();
        this.togglePlay();
      } else if (e.key === 'n' || e.key === 'N') {
        this.nextTrack();
      } else if (e.key === 'p' || e.key === 'P') {
        this.prevTrack();
      } else if (e.key === 'g' || e.key === 'G') {
        this.songDrawer.toggle();
      } else if (e.key === 'c' || e.key === 'C') {
        this.joinModal.open();
      } else if (e.key === '1') {
        this.scene3d.setCameraPreset('arena');
      } else if (e.key === '2') {
        this.scene3d.setCameraPreset('mandvi');
      } else if (e.key === '3') {
        this.scene3d.setCameraPreset('dancer');
      } else if (e.key === '4') {
        this.scene3d.setCameraPreset('topdown');
      }
    });
  }

  toast(html) {
    const toastEl = document.getElementById('toast');
    toastEl.innerHTML = html;
    toastEl.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => toastEl.classList.remove('show'), 3200);
  }
}

// Boot application when DOM is ready
window.addEventListener('DOMContentLoaded', () => {
  const app = new GarbaApp();
  app.init();
});
